class Solution {
    public long maximumStrength(int[] nums, int k) {
        int n = nums.length;
        long[][] dp = new long[n + 1][k + 1];
        for (int i = 0; i <= n; i++) Arrays.fill(dp[i], -10000000000000000L);
        dp[0][0] = 0;
        for (int j = 1; j <= k; j++) {
            long w = (j % 2 == 1) ? (k - j + 1) : -(k - j + 1);
            long mx = -10000000000000000L;
            for (int i = j; i <= n; i++) {
                mx = Math.max(mx, dp[i - 1][j - 1]);
                dp[i][j] = w * nums[i - 1] + Math.max(dp[i - 1][j], mx);
            }
        }
        long ans = -10000000000000000L;
        for (int i = k; i <= n; i++) ans = Math.max(ans, dp[i][k]);
        return ans;
    }
}

var maximumStrength = function(nums, k) {
    const n = nums.length;
    const dp = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(-Infinity));
    dp[0][0] = 0;
    for (let j = 1; j <= k; ++j) {
        const w = BigInt((j % 2 === 1) ? (k - j + 1) : -(k - j + 1));
        let mx = -Infinity;
        for (let i = j; i <= n; ++i) {
            mx = Math.max(mx, dp[i - 1][j - 1]);
            const val = Number(w * BigInt(nums[i - 1]));
            dp[i][j] = val + Math.max(dp[i - 1][j], mx);
        }
    }
    let ans = -Infinity;
    for (let i = k; i <= n; ++i) ans = Math.max(ans, dp[i][k]);
    return ans;
};
